// Disegni delle icone del gioco (griglia 24×24, contorno inchiostro, colori pieni della palette del gioco).
// La chiave è il carattere dell'emoji che l'icona sostituisce (vedi src/ui/icons.ts).
// Forme: C cerchio, E ellisse, R rettangolo arrotondato, P tracciato pieno, L linea; `N` = senza contorno,
// HL = riflesso bianco.
export type Shape = { d: string; f?: string; s?: string | 0; w?: number; o?: number };
type O = Partial<Shape>;

export const K = '#3a2f55';
export const Y = '#ffc21a';
export const YL = '#ffe08a';
export const O_ = '#ff8a3d';
export const RD = '#ff5d73';
export const RR = '#e8463c';
export const G = '#35c46a';
export const GL = '#9be07a';
export const GD = '#1f9a4c';
export const B = '#2d9cdb';
export const BL = '#9fd8ff';
export const P_ = '#8e5bd6';
export const PL = '#c9a8f0';
export const W = '#ffffff';
export const CR = '#fff2d6';
export const BR = '#c98a4b';
export const BRL = '#e8b77a';
export const BRD = '#8a5a33';
export const GY = '#c4cadb';
export const GYD = '#66708a';
export const SK = '#ffcf9e';
export const PK = '#ff9ec4';

const n = (v: number) => +v.toFixed(2);
export const circ = (x: number, y: number, r: number) =>
  `M${n(x - r)} ${n(y)}a${n(r)} ${n(r)} 0 1 0 ${n(2 * r)} 0a${n(r)} ${n(r)} 0 1 0 ${n(-2 * r)} 0Z`;
export const ell = (x: number, y: number, rx: number, ry: number) =>
  `M${n(x - rx)} ${n(y)}a${n(rx)} ${n(ry)} 0 1 0 ${n(2 * rx)} 0a${n(rx)} ${n(ry)} 0 1 0 ${n(-2 * rx)} 0Z`;
export const rr = (x: number, y: number, w: number, h: number, r = 0) => {
  r = Math.min(r, w / 2, h / 2);
  if (!r) return `M${n(x)} ${n(y)}h${n(w)}v${n(h)}h${n(-w)}Z`;
  return `M${n(x + r)} ${n(y)}h${n(w - 2 * r)}a${n(r)} ${n(r)} 0 0 1 ${n(r)} ${n(r)}v${n(h - 2 * r)}a${n(r)} ${n(r)} 0 0 1 ${n(-r)} ${n(r)}h${n(
    -(w - 2 * r),
  )}a${n(r)} ${n(r)} 0 0 1 ${n(-r)} ${n(-r)}v${n(-(h - 2 * r))}a${n(r)} ${n(r)} 0 0 1 ${n(r)} ${n(-r)}Z`;
};
/** stella a `k` punte */
export const star = (x: number, y: number, R: number, r: number, k = 5) => {
  let d = '';
  for (let i = 0; i < k * 2; i++) {
    const a = (Math.PI * i) / k - Math.PI / 2;
    const q = i % 2 ? r : R;
    d += `${i ? 'L' : 'M'}${n(x + Math.cos(a) * q)} ${n(y + Math.sin(a) * q)}`;
  }
  return d + 'Z';
};

export const C = (x: number, y: number, r: number, f: string, o: O = {}): Shape => ({ d: circ(x, y, r), f, ...o });
export const E = (x: number, y: number, rx: number, ry: number, f: string, o: O = {}): Shape => ({ d: ell(x, y, rx, ry), f, ...o });
export const R = (x: number, y: number, w: number, h: number, r: number, f: string, o: O = {}): Shape => ({ d: rr(x, y, w, h, r), f, ...o });
export const P = (d: string, f: string, o: O = {}): Shape => ({ d, f, ...o });
export const L = (d: string, s: string = K, w = 1.5, o: O = {}): Shape => ({ d, s, w, ...o });
export const N: O = { s: 0 };
export const HL = (d: string, o = 0.6): Shape => ({ d, f: W, s: 0, o });
export const ST = (x: number, y: number, R_: number, f: string, o: O = {}): Shape => ({ d: star(x, y, R_, R_ * 0.45), f, ...o });

