const square = (c: string) => [R(4, 4, 16, 16, 3.5, c), HL(rr(6.5, 6.5, 5, 2.2, 1.1))];
const arrow = (rot: number) => {
  // freccia spessa verso destra ruotata di `rot` gradi
  const pts: [number, number][] = [[4, 9.5], [12.5, 9.5], [12.5, 5], [20, 12], [12.5, 19], [12.5, 14.5], [4, 14.5]];
  const a = (rot * Math.PI) / 180;
  const d = pts
    .map(([x, y], i) => {
      const dx = x - 12, dy = y - 12;
      return `${i ? 'L' : 'M'}${n(12 + dx * Math.cos(a) - dy * Math.sin(a))} ${n(12 + dx * Math.sin(a) + dy * Math.cos(a))}`;
    })
    .join('');
  return [R(2.5, 2.5, 19, 19, 4.5, B), P(d + 'Z', W, { w: 1.2 })];
};
