const building = (c: string, w: number, h: number, win = BL) => {
  const x = 12 - w / 2, y = 22 - h;
  const out: Shape[] = [R(x, y, w, h - 0.5, 1, c)];
  for (let yy = y + 2; yy < 18; yy += 3.6) for (let xx = x + 1.8; xx < x + w - 2.5; xx += 3.4) out.push(R(xx, yy, 2, 2.2, 0.3, win, { w: 0.9 }));
  out.push(R(10.5, 18, 3, 3.5, 0.4, BRD, { w: 1 }));
  return out;
};
